CREATE TABLE IF NOT EXISTS token_usage_sources (engine TEXT NOT NULL, source TEXT NOT NULL, task_id TEXT NOT NULL, timestamp TEXT NOT NULL,total_tokens INTEGER,input_tokens INTEGER,output_tokens INTEGER,cache_read_tokens INTEGER,cache_write_tokens INTEGER, PRIMARY KEY(engine,source));
CREATE TABLE IF NOT EXISTS token_usage_daily (day TEXT NOT NULL, engine TEXT NOT NULL, task_id TEXT NOT NULL,total_tokens INTEGER,input_tokens INTEGER,output_tokens INTEGER,cache_read_tokens INTEGER,cache_write_tokens INTEGER, PRIMARY KEY(day,engine,task_id));
CREATE INDEX IF NOT EXISTS token_usage_daily_engine_day ON token_usage_daily(engine,day);
CREATE TRIGGER IF NOT EXISTS token_usage_accumulate AFTER UPDATE ON token_usage_sources WHEN NEW.total_tokens IS NOT OLD.total_tokens OR NEW.input_tokens IS NOT OLD.input_tokens OR NEW.output_tokens IS NOT OLD.output_tokens OR NEW.cache_read_tokens IS NOT OLD.cache_read_tokens OR NEW.cache_write_tokens IS NOT OLD.cache_write_tokens BEGIN INSERT INTO token_usage_daily VALUES (substr(NEW.timestamp,1,10),NEW.engine,NEW.task_id,CASE WHEN NEW.total_tokens IS NULL OR OLD.total_tokens IS NULL THEN NULL ELSE MAX(0, NEW.total_tokens-COALESCE(OLD.total_tokens,0)) END,CASE WHEN NEW.input_tokens IS NULL OR OLD.input_tokens IS NULL THEN NULL ELSE MAX(0, NEW.input_tokens-COALESCE(OLD.input_tokens,0)) END,CASE WHEN NEW.output_tokens IS NULL OR OLD.output_tokens IS NULL THEN NULL ELSE MAX(0, NEW.output_tokens-COALESCE(OLD.output_tokens,0)) END,CASE WHEN NEW.cache_read_tokens IS NULL OR OLD.cache_read_tokens IS NULL THEN NULL ELSE MAX(0, NEW.cache_read_tokens-COALESCE(OLD.cache_read_tokens,0)) END,CASE WHEN NEW.cache_write_tokens IS NULL OR OLD.cache_write_tokens IS NULL THEN NULL ELSE MAX(0, NEW.cache_write_tokens-COALESCE(OLD.cache_write_tokens,0)) END) ON CONFLICT(day,engine,task_id) DO UPDATE SET total_tokens=CASE WHEN total_tokens IS NULL AND excluded.total_tokens IS NULL THEN NULL ELSE COALESCE(total_tokens,0)+COALESCE(excluded.total_tokens,0) END,input_tokens=CASE WHEN input_tokens IS NULL AND excluded.input_tokens IS NULL THEN NULL ELSE COALESCE(input_tokens,0)+COALESCE(excluded.input_tokens,0) END,output_tokens=CASE WHEN output_tokens IS NULL AND excluded.output_tokens IS NULL THEN NULL ELSE COALESCE(output_tokens,0)+COALESCE(excluded.output_tokens,0) END,cache_read_tokens=CASE WHEN cache_read_tokens IS NULL AND excluded.cache_read_tokens IS NULL THEN NULL ELSE COALESCE(cache_read_tokens,0)+COALESCE(excluded.cache_read_tokens,0) END,cache_write_tokens=CASE WHEN cache_write_tokens IS NULL AND excluded.cache_write_tokens IS NULL THEN NULL ELSE COALESCE(cache_write_tokens,0)+COALESCE(excluded.cache_write_tokens,0) END; END;
